# =============================================================================
# DATASET CONFIGURATION
# =============================================================================
NUM_CLASSES = 15501
IMG_SIZE = 256  # Increased resolution for fine-grained details
NUM_CHANNELS = 3
MEAN = [0.485, 0.456, 0.406]  # ImageNet mean
STD = [0.229, 0.224, 0.225]  # ImageNet std

# Debugging/Development flags
# Set to a small integer (e.g., 1000) to limit dataset size for quick testing.
# Set to None to use the full dataset.
DEBUG_SAMPLE_SIZE = None

# =============================================================================
# MODEL AND TRAINING HYPERPARAMETERS
# =============================================================================
MODEL_NAME = "resnet50"
FREEZE_BACKBONE = False  # Fine-tuning strategy

BATCH_SIZE = 128  # Adjusted for ResNet50 on A100 GPU
NUM_EPOCHS = 4  # Adjusted for fine-tuning within time limits
LEARNING_RATE = 1e-3  # Head LR
BACKBONE_LR = 1e-4  # Backbone LR (Differential Learning Rate)
WEIGHT_DECAY = 1e-4

# Early Stopping parameters
PATIENCE = 2
MIN_DELTA = 0.001

# =============================================================================
# COMPUTE SETTINGS
# =============================================================================
SEED = 42
NUM_WORKERS = 12  # Using available vCPUs
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")


def set_seed(seed=SEED):
    """
    Sets the random seed for reproducibility across Python, NumPy, and PyTorch.

    Args:
        seed (int): The seed value to use. Defaults to config.SEED.
    """
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed(seed)
    torch.backends.cudnn.deterministic = True
    torch.backends.cudnn.benchmark = False
    os.environ["PYTHONHASHSEED"] = str(seed)


# Initialize seed immediately upon import
set_seed()
